package com.workworth.earnings.persistence;
import com.workworth.earnings.domain.EarningStatus; import com.workworth.salary.domain.IncomeSource; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*; import lombok.Getter;
@Getter @Entity @Table(name="workday_earnings") public class WorkdayEarning { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="workday_id",nullable=false,unique=true) private Long workdayId; @Column(name="local_date",nullable=false) private LocalDate localDate; @Column(name="reference_month",nullable=false,length=7) private String referenceMonth; @Enumerated(EnumType.STRING) @Column(nullable=false) private EarningStatus status; @Column(name="economic_seconds",nullable=false) private long economicSeconds; @Column(name="raw_amount",precision=24,scale=12) private BigDecimal rawAmount; @Column(name="salary_profile_id") private Long salaryProfileId; @Enumerated(EnumType.STRING) @Column(name="income_source") private IncomeSource incomeSource; @Column(name="monthly_net",precision=19,scale=2) private BigDecimal monthlyNet; @Column(name="annual_net",precision=19,scale=2) private BigDecimal annualNet; @Column(name="pay_periods") private Integer payPeriods; @Column(name="currency_code",length=3) private String currencyCode; @Column(name="standard_hours",precision=24,scale=12) private BigDecimal standardHours; @Column(name="hourly_rate",precision=24,scale=12) private BigDecimal hourlyRate; @Column(name="materialized_at",nullable=false) private Instant materializedAt; protected WorkdayEarning(){} public WorkdayEarning(Long workdayId,LocalDate date,EarningStatus status,long seconds,BigDecimal amount,Long profile,IncomeSource source,BigDecimal monthly,BigDecimal annual,int periods,String currency,BigDecimal hours,BigDecimal rate,Instant at){this.workdayId=workdayId;localDate=date;referenceMonth=YearMonth.from(date).toString();this.status=status;economicSeconds=seconds;rawAmount=amount;salaryProfileId=profile;incomeSource=source;monthlyNet=monthly;annualNet=annual;payPeriods=periods;currencyCode=currency;standardHours=hours;hourlyRate=rate;materializedAt=at;} }
